#include <omp.h>
#include <vector>
#include <string>
#include <cstddef>
#include <algorithm>

struct Book {
   std::string title;
   int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const std::size_t n = books.size();
    if (n == 0) return n; // sentinel "not found"

    std::size_t globalLast = n; // sentinel; will hold max index found

#pragma omp parallel
    {
        std::size_t localLast = n;

#pragma omp for nowait
        for (std::size_t i = 0; i < n; ++i) {
            if (books[i].pages < 100) {
                localLast = (localLast == n) ? i : std::max(localLast, i);
            }
        }

#pragma omp critical
        {
            if (localLast != n) {
                if (globalLast == n) globalLast = localLast;
                else globalLast = std::max(globalLast, localLast);
            }
        }
    }

    return globalLast; // returns books.size() if not found
}
